def discover_existing_modules(workflow: str, base_path: str = None) -> Dict[str, List[Dict]]:
    """
    Discover existing framework modules for a given workflow/domain.

    IMPORTANT: Before generating new modules, check if modules already exist
    for the workflow. If they do, use existing modules instead of creating duplicates.

    Args:
        workflow: Workflow domain (auth, catalog, cart, checkout, common)
        base_path: Optional base path to framework (defaults to relative path)

    Returns:
        Dict with existing modules by type:
        {
            "pages": [{"name": "LoginPage", "path": "...", "class_name": "..."}],
            "tasks": [...],
            "roles": [...]
        }
    """
    from pathlib import Path
    import ast

    if base_path:
        framework_path = Path(base_path)
    else:
        # Default: assume we're in mcp_server/utils, go up to project root
        framework_path = Path(__file__).parent.parent.parent / "framework"

    result = {
        "pages": [],
        "tasks": [],
        "roles": [],
        "workflow": workflow,
        "has_existing_modules": False
    }

    # Map workflow aliases
    workflow_aliases = {
        "auth": ["auth", "authentication", "login"],
        "catalog": ["catalog", "category", "product", "browse"],
        "cart": ["cart", "basket", "shopping"],
        "checkout": ["checkout", "payment", "order"],
        "common": ["common"]
    }

    # Get all possible folder names for this workflow
    folders_to_check = workflow_aliases.get(workflow, [workflow])

    def extract_classes_from_file(file_path: Path) -> List[str]:
        """Extract class names from a Python file."""
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                tree = ast.parse(f.read())
            return [node.name for node in ast.walk(tree) if isinstance(node, ast.ClassDef)]
        except Exception:
            return []

    # Check pages
    pages_base = framework_path / "pages"
    for folder in folders_to_check:
        folder_path = pages_base / folder
        if folder_path.exists():
            for py_file in folder_path.glob("*.py"):
                if py_file.name.startswith("_"):
                    continue
                classes = extract_classes_from_file(py_file)
                for cls in classes:
                    if cls != "BasePage":  # Skip base class
                        result["pages"].append({
                            "name": cls,
                            "path": str(py_file.relative_to(framework_path.parent)),
                            "file": py_file.name
                        })

    # Check tasks
    tasks_base = framework_path / "tasks"
    for folder in folders_to_check:
        folder_path = tasks_base / folder
        if folder_path.exists():
            for py_file in folder_path.glob("*.py"):
                if py_file.name.startswith("_"):
                    continue
                classes = extract_classes_from_file(py_file)
                for cls in classes:
                    result["tasks"].append({
                        "name": cls,
                        "path": str(py_file.relative_to(framework_path.parent)),
                        "file": py_file.name
                    })

    # Check roles
    roles_base = framework_path / "roles"
    for folder in folders_to_check:
        folder_path = roles_base / folder
        if folder_path.exists():
            for py_file in folder_path.glob("*.py"):
                if py_file.name.startswith("_"):
                    continue
                classes = extract_classes_from_file(py_file)
                for cls in classes:
                    if cls != "Role":  # Skip base class
                        result["roles"].append({
                            "name": cls,
                            "path": str(py_file.relative_to(framework_path.parent)),
                            "file": py_file.name
                        })

    # Check if any existing modules found
    result["has_existing_modules"] = bool(
        result["pages"] or result["tasks"] or result["roles"]
    )

    return result


def check_module_exists(component_type: str, workflow: str, base_path: str = None) -> Optional[Dict]:
    """
    Check if a module already exists for the given component type and workflow.

    Args:
        component_type: "page", "task", or "role"
        workflow: Workflow domain (auth, catalog, etc.)
        base_path: Optional base path

    Returns:
        Dict with existing module info if found, None otherwise
    """
    existing = discover_existing_modules(workflow, base_path)

    type_map = {
        "page": "pages",
        "task": "tasks",
        "role": "roles"
    }

    modules = existing.get(type_map.get(component_type, ""), [])

    if modules:
        return {
            "exists": True,
            "modules": modules,
            "message": f"Found {len(modules)} existing {component_type}(s) for '{workflow}' workflow. "
                      f"Use existing modules instead of creating duplicates.",
            "recommendation": "USE_EXISTING"
        }

    return None

